fields.InputDefinition:
{
  "goal": "Open the 'Members' entity grid — type 'Members' in the LEFT sidebar 'Search entities...' box and click the EXACT 'Members' match (not 'Board Members'/'Memberships'/etc.); if that is giving you trouble, navigate directly to http://localhost:4200/app/data-explorer/Data?entity=Members. Then click a member row and click 'Open Full Record'. The Member form has MANY related-records sections (Memberships, Event Registrations, Invoices, Certifications, Enrollments, etc.). Scroll down the form to the related-records area and open/expand ANY ONE related section; verify it displays that member's related rows (or a valid empty-state). Opening any one related section satisfies the goal — you do NOT need a specific one. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 50,
  "judgeValidationCriteria": [
    "A Member record full form is open",
    "At least one related-records section is shown with related rows or a valid empty-state",
    "No error messages, blank screens, or crash pages"
  ]
}
